/* Lumen service worker (generated by scripts/postbuild.mjs). */
const CACHE = '__CACHE_NAME__';
const PRECACHE = /* __PRECACHE__ */ [];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  );
});

// A new version replaces the old cache.
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// Cache first, network as a fallback; pages fall back to the cached game.
self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  event.respondWith(
    caches
      .match(request, { ignoreSearch: true, ignoreVary: true })
      .then(
        (cached) =>
          cached ??
          fetch(request).catch(() =>
            request.mode === 'navigate'
              ? caches.match('./index.html', { ignoreVary: true })
              : Response.error(),
          ),
      ),
  );
});
